export function parseDescription(text) {
  let t = (text || "").replace(/https?:\/\/\S+/g, "").replace(/\s*[—–]\s*/g, ", ").replace(/\s+/g, " ").trim();
  if (!t) return { features: [], blurb: "" };
  let parts = null;
  if (t.includes("[+]")) {
    parts = t.split(/\[\+\]/);
  } else if (/(?:^|\s)[-•]\s/.test(t)) {
    parts = t.split(/(?:^|\s)[-•]\s+/);
  }
  if (!parts) return { features: [], blurb: t };
  let features = parts
    .map(p => p.trim().replace(/^[\s:.-]+|[\s:.-]+$/g, ""))
    .filter(p => p.length > 1 && p.length <= 90);
  return features.length ? { features, blurb: "" } : { features: [], blurb: t };
}

export function cleanGameName(name) {
  return name.replace(/^\s*\[[^\]]*\]\s*/, "").trim() || name;
}

export function normalizeSortKey(name) {
  let cleaned = cleanGameName(name);
  return ((/^[\p{L}\p{N}]/u.test(cleaned) ? cleaned : cleaned.replace(/^[^\p{L}]+/u, "").trim()) || cleaned).toLowerCase();
}

export function processGamesData(data) {
  let map = new Map();
  for (let g of data.games) {
    let existing = map.get(g.placeId);
    if (!existing) {
      map.set(g.placeId, { ...g, aliases: [], scripts: [...g.scripts] });
      continue;
    }
    existing.aliases.push(g.name);
    let idSet = new Set(existing.scripts.map(s => s.id));
    for (let s of g.scripts) {
      if (!idSet.has(s.id)) existing.scripts.push(s);
    }
    existing.thumbnailUrl = existing.thumbnailUrl || g.thumbnailUrl;
  }

  return Array.from(map.values())
    .map(g => ({
      placeId: g.placeId,
      name: cleanGameName(g.name),
      rawName: g.name,
      sortKey: normalizeSortKey(g.name),
      aliases: g.aliases,
      url: g.robloxUrl,
      thumb: g.thumbnailUrl,
      count: g.scripts.length,
      likes: g.scripts.reduce((acc, s) => acc + (s.likes || 0), 0),
      dislikes: g.scripts.reduce((acc, s) => acc + (s.dislikes || 0), 0),
      views: g.scripts.reduce((acc, s) => acc + (s.views || 0), 0),
      patched: g.scripts.length > 0 && g.scripts.every(s => s.isPatched),
      keyless: g.scripts.some(s => !s.isKeySystem),
      latest: g.scripts.reduce((acc, s) => {
        let n = Date.parse(s.lastUpdatedAt || s.createdAt || "");
        return Number.isNaN(n) ? acc : Math.max(acc, n);
      }, 0),
      added: g.scripts.reduce((acc, s) => {
        let n = Date.parse(s.createdAt || "");
        return Number.isNaN(n) ? acc : Math.max(acc, n);
      }, 0),
      search: [g.name, cleanGameName(g.name), ...g.aliases].join(" ").toLowerCase(),
      scripts: g.scripts.map(s => ({
        id: s.id,
        title: s.title,
        url: s.url || ("https://rscripts.net/script/" + s.slug),
        rawScript: s.rawScript,
        views: s.views || 0,
        likes: s.likes || 0,
        dislikes: s.dislikes || 0,
        patched: !!s.isPatched,
        mobile: !!s.isMobileReady,
        ...parseDescription(s.description)
      }))
    }))
    .map(g => ({
      ...g,
      ratio: g.likes + g.dislikes > 0 ? g.likes / (g.likes + g.dislikes) : null
    }))
    .sort((a, b) => a.sortKey.localeCompare(b.sortKey, "en", { sensitivity: "base" }));
}

export const gamesList = processGamesData(rawData);

let scriptIdSet = new Set();
for (let g of rawData.games) {
  for (let s of g.scripts) scriptIdSet.add(s.id);
}

export const totals = {
  games: gamesList.length,
  live: gamesList.filter(g => g.count > 0).length,
  scripts: scriptIdSet.size,
  views: rawData.totals.views || 1519037,
  updated: rawData.generatedAt
};

export const recentlyAdded = [...gamesList]
  .filter(g => g.added > 0)
  .sort((a, b) => b.added - a.added)
  .slice(0, 8);

const sortScore = s => s ?? -1;

export const sortOptions = [
  { id: "name", label: "A–Z", cmp: (a, b) => a.sortKey.localeCompare(b.sortKey, "en", { sensitivity: "base" }) },
  { id: "likes", label: "Most liked", cmp: (a, b) => b.likes - a.likes },
  { id: "rating", label: "Best rated", cmp: (a, b) => (sortScore(b.ratio) - sortScore(a.ratio)) || (b.likes - a.likes) },
  { id: "dislikes", label: "Most disliked", cmp: (a, b) => b.dislikes - a.dislikes },
  { id: "views", label: "Most viewed", cmp: (a, b) => b.views - a.views },
  { id: "updated", label: "Recently updated", cmp: (a, b) => b.latest - a.latest },
  { id: "added", label: "Recently added", cmp: (a, b) => b.added - a.added }
];

export function formatCompactNumber(num) {
  if (num == null) return "-";
  if (num < 1000) return String(num);
  if (num < 1000000) return (num / 1000).toFixed(num < 10000 ? 1 : 0).replace(/\.0$/, "") + "K";
  return (num / 1000000).toFixed(num < 10000000 ? 1 : 0).replace(/\.0$/, "") + "M";
}

const relativeTimeFormatter = new Intl.RelativeTimeFormat("en", { numeric: "auto" });

export function formatRelativeTime(timestamp) {
  if (!timestamp) return null;
  let days = Math.round((timestamp - Date.now()) / 86400000);
  if (days > -1) return "today";
  if (days > -30) return relativeTimeFormatter.format(days, "day");
  if (days > -365) return relativeTimeFormatter.format(Math.round(days / 30), "month");
  return relativeTimeFormatter.format(Math.round(days / 365), "year");
}

export function calcLikePercentage(likes = 0, dislikes = 0) {
  let sum = (likes || 0) + (dislikes || 0);
  return sum > 0 ? Math.round((likes / sum) * 100) : null;
}
